const admin = require('firebase-admin');
const serviceAccount = require('./krank-club-firebase-adminsdk-bl4zy-d8facdf022.json');
const PROJECT_ID = 'krank-club'; // Replace with your project ID

admin.initializeApp({
    credential: admin.credential.cert(serviceAccount),
    projectId: PROJECT_ID,
});

const db = admin.firestore();
const gamesCollection = db.collection('games');

async function setGamesStatusToPublished(gameIds) {
    try {
        if (gameIds.length === 0) {
            console.log('No game IDs provided.');
            return;
        }

        const gamesBatch = db.batch();

        for (const gameId of gameIds) {
            const gameDocRef = gamesCollection.doc(gameId);
            gamesBatch.update(gameDocRef, { status: 'published' });
            console.log(`Updated 'status' for game ${gameId}`);
        }

        await gamesBatch.commit();
        console.log('Batch update completed successfully.');
    } catch (error) {
        console.error('Error updating documents:', error);
    } finally {
        admin.app().delete();
    }
}

